// MT2009_PLUS_SASH_SERPENT_V1 (tracked): a sash (Szarfa) keeps the random base bonuses of the serpent weapon or armour
// it absorbed in its own yextra (bits 8-31, the piece's bytes as they were; bits 0-7 unused on a sash) - the owner,
// 8 Nov 2026: "Bronie wezowe po absorpcji bonusow do szarfy nie daja bonusow ktore sa wbudowane w bron". The sash
// gives them at its absorption rate (CalcAcceBonus), at the absorbed piece's refine level (ACCE_ABSORBED_SOCKET).
static bool Mt2009YSetsIsSash(LPITEM item)
{
	return item && item->GetType() == ITEM_COSTUME && item->GetSubType() == COSTUME_ACCE;
}

static bool Mt2009YSetsTracked(LPITEM item)
{
	int iKind, iLevel;
	return Mt2009YSetsPart(item) != 0 || Mt2009YSetsRandomFamily(item->GetVnum(), iKind, iLevel) || Mt2009YSetsIsSash(item);
}

// MT2009_PLUS_SASH_SERPENT_V1 (helpers): the serpent family of the piece a sash absorbed (the hood is a helmet: never)
static bool Mt2009YSetsSashFamily(LPITEM sash, int& iKind, int& iLevel)
{
	const long lVnum = sash->GetSocket(ACCE_ABSORBED_SOCKET);
	if (lVnum <= 0 || !Mt2009YSetsRandomFamily((DWORD) lVnum, iKind, iLevel))
		return false;
	return iKind != YSETS_HOOD_KIND;
}

// a sash that absorbed a serpent piece before MT2009_PLUS_SASH_SERPENT_V1 has no lines (the piece and its yextra are
// gone): it rolls them once, for the absorbed piece's kind - before its points are added, never while they are on
static void Mt2009YSetsSashLegacy(LPITEM sash)
{
	int iKind, iLevel;
	if (!Mt2009YSetsIsSash(sash) || !sash->GetID() || (sash->GetYExtra() >> 8) || !Mt2009YSetsSashFamily(sash, iKind, iLevel))
		return;
	Mt2009YSetsRoll(sash, iKind);
	Mt2009YSetsSave(sash);
	sys_log(0, "SASH_SERPENT: sash %u (absorbed %ld) had no lines - rolled %08x", sash->GetID(),
			sash->GetSocket(ACCE_ABSORBED_SOCKET), sash->GetYExtra());
	if (sash->GetOwner() && (sash->GetWindow() == INVENTORY || sash->GetWindow() == EQUIPMENT))
		Mt2009YSetsNotify(sash->GetOwner(), 1, sash->GetCell(), sash->GetYExtra());
}

// char.cpp CleanAcceAttr (USE_DETACHMENT on a sash): the absorbed piece goes, its lines with it
void Mt2009YSetsSashClear(LPITEM sash)
{
	if (!Mt2009YSetsIsSash(sash) || !(sash->GetYExtra() >> 8))
		return;
	sash->SetYExtra(sash->GetYExtra() & 0xFFU);
	Mt2009YSetsSave(sash);
	if (sash->GetOwner() && (sash->GetWindow() == INVENTORY || sash->GetWindow() == EQUIPMENT))
		Mt2009YSetsNotify(sash->GetOwner(), 1, sash->GetCell(), sash->GetYExtra());
}

